require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';zorunlu_rol('admin','yetkili');$u=kullanici_bilgi();$sid=(int)($_GET['sporcu_id']??$_POST['sporcu_id']??0);$q=$pdo->prepare('SELECT * FROM sporcular WHERE id=?');$q->execute([$sid]);$sporcu=$q->fetch();if(!$sporcu)exit('Sporcu bulunamadı.');
if($u['rol']==='yetkili'){$k=$pdo->prepare('SELECT 1 FROM yetkili y WHERE y.user_id=? AND y.takim_id=? UNION SELECT 1 FROM takimlar WHERE yonetici_user_id=? AND id=?');$k->execute([$u['id'],$sporcu['takim_id'],$u['id'],$sporcu['takim_id']]);if(!$k->fetch())exit('Bu sporcu için işlem yetkiniz yok.');}
